// Generated by esquadro: do not edit. What an error of the API means to
// people, in the frontend's words.
import { isApiError } from "@api"
import { t } from "./i18n.ts"
import type { FieldMeta } from "./meta.ts"

/**
 * Whether an error is a business rule of the app's refusing (Broken, in
 * <entity>_rules.go): its title is the project's own text, in its
 * language.
 */
export function isRule(e: unknown): boolean {
  return isApiError(e) && e.status === 422 && e.code !== "invalid_fields" && e.code !== "too_many_records" && e.code !== "import_refused" && e.code !== "too_many_rows"
}

/** The message of an error, for a notice. */
export function describe(e: unknown): string {
  if (isApiError(e) && isRule(e)) return e.title
  // The frontend's own words, in its language: the API's titles are in
  // English.
  if (isApiError(e)) {
    if (e.code === "precondition_failed") return t("conflict")
    if (e.code === "reauthentication_required") return t("reauthenticate")
    if (e.code === "last_credential") return t("lastCredential")
    if (e.code === "invalid_fields") return t("fixFields")
    if (e.code === "invalid_link") return t("invalidLink")
    if (e.code === "too_soon") return t("tooSoon")
    if (e.code === "own_account") return t("ownAccountHint")
    if (e.code === "last_administrator") return t("lastAdministrator")
    if (e.code === "already_active") return t("alreadyActive")
    if (e.code === "already_verified") return t("alreadyVerified")
    if (e.status === 400) return t("badRequest")
    if (e.status === 401) return t("sessionEnded")
    if (e.status === 403) return t("forbidden")
    if (e.status === 404) return t("notFound")
    if (e.status === 409) return t("conflict")
    if (e.status === 429) return t("tooMany")
    if (e.status >= 500) return t("serverError")
  }
  if (e instanceof TypeError) return t("offline")
  return t("somethingWrong")
}

/** What is wrong with a field, as people read it, from the API's code. */
export function fieldMessage(field: FieldMeta, code: string): string {
  if (code.startsWith(ruleMark)) return code.slice(ruleMark.length)
  switch (code) {
    case "required":
      return field.kind === "enum" || field.kind === "relation" ? t("fieldChoose") : t("fieldRequired")
    case "too_short":
      return t("fieldTooShort")
    case "too_long":
      return t("fieldTooLong")
    case "too_small":
      return t("fieldTooSmall")
    case "too_large":
      return t("fieldTooLarge")
    case "pattern":
      return t("fieldPattern")
    case "invalid_type":
      return t("fieldFileType")
    case "unique":
    case "taken":
    case "in_use":
      return t("fieldTaken")
    case "not_found":
    case "foreign_key":
      return t("fieldGone")
    case "ambiguous":
      return t("fieldAmbiguous")
  }
  return t("fieldInvalid")
}

/** The fields an error refused, by name, with why: required, too_long... */
export function fieldErrors(e: unknown): Record<string, string> {
  const out: Record<string, string> = {}
  if (isApiError(e)) {
    // A rule's refusal shows its own text on its fields.
    for (const f of e.fields) out[f.field] = isRule(e) ? ruleMark + e.title : f.code
  }
  return out
}

/** Marks a field's error as a rule's text, not a code. */
const ruleMark = "rule:"

/**
 * Whether a query is tried again after an error: a refusal is final (400,
 * 403, 404), but too many requests (429) and a server's error are tried
 * again, a few times.
 */
export function retryQuery(failures: number, e: unknown): boolean {
  if (isApiError(e) && e.status === 429) return failures < 4
  return !(isApiError(e) && e.status < 500) && failures < 2
}

/** How long before trying again: longer each time, a little at random (many at once spread out). */
export function retryDelay(failures: number): number {
  return Math.min(8000, 600 * 2 ** failures) + Math.random() * 400
}
